import { isRoundInProgress, type SlotApiEntry, type SlotApiJackpotPoolSnapshot, type SlotApiJackpotsResponse, type SlotApiJackpotTier } from './SlotApiTypes';
import type { SlotGridLayout } from '../models/SlotGrid';
import { WinTier, type WinTierThreshold } from '../config/GameConst';

const STRIP_LEN = 30;

/**
 * 後端的大獎門檻轉成演出等級門檻（由大到小）。
 *
 * @param wt entry 的 `wt`，底注倍數字串。
 * @returns 門檻清單；`"0"` 或不是數字的那一檔不放進去（不播），最後一筆是小報獎。
 */
export function toWinTierThresholds(wt: SlotApiEntry['wt']): WinTierThreshold[] {
    const tiers: WinTierThreshold[] = [
        { min: Number(wt.bw), key: WinTier.BIG },
        { min: Number(wt.mgw), key: WinTier.MEGA },
        { min: Number(wt.smgw), key: WinTier.SUPER },
        { min: Number(wt.epw), key: WinTier.EPIC },
    ].filter((tier) => Number.isFinite(tier.min) && tier.min > 0);
    tiers.sort((a, b) => b.min - a.min);
    tiers.push({ min: 0, key: WinTier.WIN });
    return tiers;
}

const STRIP_SYMBOL_NAMES = ['symbol_h1', 'symbol_h2', 'symbol_h3', 'symbol_h4', 'symbol_l1', 'symbol_l2', 'symbol_l3', 'symbol_l4', 'symbol_l5', 'symbol_m1_1', 'symbol_m2_1', 'symbol_scatter'];

function makeIconMatrix(columns: number): string[][] {
    const matrix: string[][] = [];
    for (let i = 0; i < columns; i++) {
        const strip: string[] = [];
        for (let j = 0; j < STRIP_LEN; j++) {
            strip.push(STRIP_SYMBOL_NAMES[(i * 7 + j * 3) % STRIP_SYMBOL_NAMES.length]);
        }
        matrix.push(strip);
    }
    return matrix;
}

/**
 * 組出盤面流程讀的 configData（`base.icon_matrix` 與買入倍率）。輪帶由前端自己產生，後端不給。
 *
 * @param layout 盤面形狀 決定欄數
 * @param buyMultiple 買入倍率 entry 的 `buy[].m`
 * @returns configData
 */
export function toSlotConfigData(layout: SlotGridLayout, buyMultiple: number): any {
    const columns = layout.columns;
    return {
        base: {
            column: columns,
            shape: [],
            icon_matrix: makeIconMatrix(columns),
        },
        client_config: {
            buy_super_multiplier: buyMultiple,
            buy_feature_multiplier: buyMultiple,
            buy_triple_multiplier: buyMultiple,
        },
        slot_game_info: null,
    };
}

// ── 十進位運算：金額與倍數都是十進位字串，不用浮點數算（規格 §4.4） ──────────

/**
 * 十進位字串拆成「整數 × 10^-scale」。
 *
 * @param value 十進位字串，例如 `"0.05"`。
 * @returns 整數部分與小數位數；空字串視為 0。
 */
function parseDecimal(value: string): { int: number; scale: number } {
    const [whole, fraction = ''] = (value || '0').split('.');
    return { int: Number(whole + fraction), scale: fraction.length };
}

/**
 * 整數與小數位數轉回十進位字串：去掉多餘的尾端 0，但至少保留 minScale 位。
 *
 * @param value 縮放後的整數。
 * @param scale 小數位數。
 * @param minScale 至少保留幾位小數（幣別小數位）。
 * @returns 十進位字串，負數帶負號。
 */
function formatScaled(value: number, scale: number, minScale: number): string {
    const digits = String(Math.abs(value)).padStart(scale + 1, '0');
    const fraction = digits.slice(digits.length - scale).replace(/0+$/, '').padEnd(minScale, '0');
    return `${value < 0 ? '-' : ''}${digits.slice(0, digits.length - scale)}${fraction ? `.${fraction}` : ''}`;
}

/**
 * 兩個十進位字串相乘。
 *
 * @param a 被乘數。
 * @param b 乘數。
 * @param minScale 結果至少保留幾位小數。
 * @returns 乘積的十進位字串。
 */
export function multiplyDecimal(a: string, b: string, minScale: number): string {
    const left = parseDecimal(a);
    const right = parseDecimal(b);
    return formatScaled(left.int * right.int, left.scale + right.scale, minScale);
}

/**
 * 兩個十進位字串相減。
 *
 * @param a 被減數。
 * @param b 減數。
 * @param minScale 結果至少保留幾位小數。
 * @returns 差的十進位字串。
 */
export function subtractDecimal(a: string, b: string, minScale: number): string {
    const left = parseDecimal(a);
    const right = parseDecimal(b);
    const scale = Math.max(left.scale, right.scale);
    return formatScaled(left.int * 10 ** (scale - left.scale) - right.int * 10 ** (scale - right.scale), scale, minScale);
}

/**
 * 底注＝Bet Size × Bet Level × Base Bet（規格 §5.1「注額怎麼算」）。
 *
 * @param size Bet Size。
 * @param level Bet Level。
 * @param baseBet entry 的 `bb`。
 * @param minScale 幣別小數位。
 * @returns 底注金額。
 */
export function baseBetAmount(size: string, level: number, baseBet: number, minScale: number): string {
    return multiplyDecimal(multiplyDecimal(size, String(level), 0), String(baseBet), minScale);
}

/** 下注清單的一項：攤平後的底注金額，以及送給後端的 size／level */
export interface SlotBetOption {
    readonly amount: string;
    readonly size: string;
    readonly level: number;
}

/**
 * 把 entry 的 Bet Size × Bet Level 攤平成現有 UI 的單一金額清單（暫時做法，規格的 UI 是兩個選擇器）。
 * 由小到大排序；總額相同的只留第一個（size 較小的那組），反查時用金額找它。
 *
 * @param entry 進場回應。
 * @returns 下注清單。
 */
export function toBetPlan(entry: SlotApiEntry): SlotBetOption[] {
    const byAmount = new Map<string, SlotBetOption>();
    const sizes = [...entry.cs].sort((a, b) => Number(a) - Number(b));
    for (const size of sizes) {
        for (const level of entry.ml) {
            const amount = baseBetAmount(size, level, entry.bb, entry.cd);
            if (!byAmount.has(amount)) byAmount.set(amount, { amount, size, level });
        }
    }
    return Array.from(byAmount.values()).sort((a, b) => Number(a.amount) - Number(b.amount));
}

/**
 * 進場資料轉成 UI 讀的 gameInitData（餘額、幣別、下注清單、預選下注額）。
 *
 * 預選下注額用 entry 的 `pre`（伺服器已經挑好：上一局的值還在列表上就用它，否則用方案預設）。
 * 局打到一半（`ls.nst` 不是 1）時，預選下注額改用本局的 `ls.cs`／`ls.ml`。
 *
 * @param entry 進場回應。
 * @param betPlan {@link toBetPlan} 攤平後的下注清單。
 * @param layout 盤面形狀，決定欄數。
 * @returns gameInitData。
 */
export function toSlotInitData(entry: SlotApiEntry, betPlan: readonly SlotBetOption[], layout: SlotGridLayout): any {
    const inProgress = isRoundInProgress(entry.ls);
    return {
        machine_info: {
            extra: {},
            bet_level: betPlan.map((option) => Number(option.amount)),
            last_bet: baseBetAmount(inProgress ? entry.ls.cs : entry.pre.cs, inProgress ? entry.ls.ml : entry.pre.ml, entry.bb, entry.cd),
            icon_indexes: Array.from({ length: layout.columns }, () => 2 + Math.floor(Math.random() * 20)),
            icon_table: [],
            spin_total_win: '0',
        },
        game: {
            balance: entry.bl,
            auth_key: '',
            currency: entry.cc,
        },
    };
}

const JACKPOT_TIERS: readonly SlotApiJackpotTier[] = ['MINI', 'MINOR', 'MAJOR', 'GRAND'];

/**
 * 獎池水位：只取玩家幣別的池，層級 1–4 對應 MINI／MINOR／MAJOR／GRAND；負值一律顯示 0。
 *
 * @param response `GET /player/jackpots` 的 `data`
 * @param gameCode 遊戲代號
 * @param currency 玩家幣別（entry 的 `cc`）
 * @returns 常駐獎池條讀的快照
 */
export function toJackpotSnapshot(response: SlotApiJackpotsResponse, gameCode: string, currency: string): SlotApiJackpotPoolSnapshot {
    return {
        game_code: gameCode,
        currency,
        pool_group_id: '',
        pools: response.pools
            .filter((pool) => pool.currency === currency && JACKPOT_TIERS[pool.tier - 1])
            .map((pool) => ({ tier: JACKPOT_TIERS[pool.tier - 1], amount: Number(pool.current_value) < 0 ? '0' : pool.current_value })),
        as_of_ms: Date.now(),
    };
}
